def tau_pow12(n):
    if n == 1:
        return 1
    # Factorize n
    d = 2
    temp = n
    factors = []
    while d * d <= temp:
        if temp % d == 0:
            count = 0
            while temp % d == 0:
                count += 1
                temp //= d
            factors.append(count)
        d += 1
    if temp > 1:
        factors.append(1)

    res = 1
    for a in factors:
        res *= (12 * a + 1)
    return res

solutions = []
for n in range(1, 10000):
    if n == tau_pow12(n):
        solutions.append(n)

print(solutions)

